      subroutine root2(ta, ua, rr, ww, n)
      use rank2
      implicit none
      integer i, j, k, n, offset, it, iu, of(2)
      double precision t, u, t2, u2, tt, uu, d(4), g(4)
      double precision ta(*), ua(*), rr(*), ww(*)
      double precision im(4, 18), imc(4, 18)
      double precision pi, o7, o14
      parameter (pi = 3.141592653589793238462643d0)
      parameter (o7  = (2.0d0 / 18.0d0))
      parameter (o14 = (1.0d0 / 18.0d0))

      call fill2

      do i = 1, n ! loop over parameter set
        t = ta(i) 
        if (t .lt. 0.0d0) cycle 
        if (t .gt. 19682.99d0) t = 19682.99d0 
        u = ua(i) 
        tt = dsqrt(t) 
        if (tt .gt. 1.0d0) tt = dlog(t) * 0.9102392266268373d0 + 1.0d0 ! log(3)+1 
        uu = dlog10(u)

        it = tt 
        tt = tt - it
        tt = 2.0d0 * tt - 1.0d0 

        iu = uu + 7 ! 0 <= iu <= 9
        if (iu < 0 .or. iu > 10) then
          print *, "current implementation assumes 1.0d-7 < U < 1.0e3"
          stop  
        else
          uu = uu - (iu - 7)
          uu = 2.0d0 * uu - 1.0d0 
        endif 

        offset = 648 * (iu + it * 10)
        u2 = uu * 2.0d0
        do j = 1, 18
          d(1) = 0.0d0
          g(1) = 0.0d0
          d(2) = 0.0d0
          g(2) = 0.0d0
          d(3) = 0.0d0
          g(3) = 0.0d0
          d(4) = 0.0d0
          g(4) = 0.0d0
          of(1) = offset + (j - 1) * 18
          of(2) = of(1) + 324
          g(1) = u2 * d(1) - g(1) + x(of(1) + 18)
          g(2) = u2 * d(2) - g(2) + x(of(2) + 18)
          g(3) = u2 * d(3) - g(3) + w(of(1) + 18)
          g(4) = u2 * d(4) - g(4) + w(of(2) + 18)
          d(1) = u2 * g(1) - d(1) + x(of(1) + 17)
          d(2) = u2 * g(2) - d(2) + x(of(2) + 17)
          d(3) = u2 * g(3) - d(3) + w(of(1) + 17)
          d(4) = u2 * g(4) - d(4) + w(of(2) + 17)
          g(1) = u2 * d(1) - g(1) + x(of(1) + 16)
          g(2) = u2 * d(2) - g(2) + x(of(2) + 16)
          g(3) = u2 * d(3) - g(3) + w(of(1) + 16)
          g(4) = u2 * d(4) - g(4) + w(of(2) + 16)
          d(1) = u2 * g(1) - d(1) + x(of(1) + 15)
          d(2) = u2 * g(2) - d(2) + x(of(2) + 15)
          d(3) = u2 * g(3) - d(3) + w(of(1) + 15)
          d(4) = u2 * g(4) - d(4) + w(of(2) + 15)
          g(1) = u2 * d(1) - g(1) + x(of(1) + 14)
          g(2) = u2 * d(2) - g(2) + x(of(2) + 14)
          g(3) = u2 * d(3) - g(3) + w(of(1) + 14)
          g(4) = u2 * d(4) - g(4) + w(of(2) + 14)
          d(1) = u2 * g(1) - d(1) + x(of(1) + 13)
          d(2) = u2 * g(2) - d(2) + x(of(2) + 13)
          d(3) = u2 * g(3) - d(3) + w(of(1) + 13)
          d(4) = u2 * g(4) - d(4) + w(of(2) + 13)
          g(1) = u2 * d(1) - g(1) + x(of(1) + 12)
          g(2) = u2 * d(2) - g(2) + x(of(2) + 12)
          g(3) = u2 * d(3) - g(3) + w(of(1) + 12)
          g(4) = u2 * d(4) - g(4) + w(of(2) + 12)
          d(1) = u2 * g(1) - d(1) + x(of(1) + 11)
          d(2) = u2 * g(2) - d(2) + x(of(2) + 11)
          d(3) = u2 * g(3) - d(3) + w(of(1) + 11)
          d(4) = u2 * g(4) - d(4) + w(of(2) + 11)
          g(1) = u2 * d(1) - g(1) + x(of(1) + 10)
          g(2) = u2 * d(2) - g(2) + x(of(2) + 10)
          g(3) = u2 * d(3) - g(3) + w(of(1) + 10)
          g(4) = u2 * d(4) - g(4) + w(of(2) + 10)
          d(1) = u2 * g(1) - d(1) + x(of(1) + 9)
