          g(4) = u2 * d(4) - g(4) + w(of(2) + 8)
          d(1) = u2 * g(1) - d(1) + x(of(1) + 7)
          d(2) = u2 * g(2) - d(2) + x(of(2) + 7)
          d(3) = u2 * g(3) - d(3) + w(of(1) + 7)
          d(4) = u2 * g(4) - d(4) + w(of(2) + 7)
          g(1) = u2 * d(1) - g(1) + x(of(1) + 6)
          g(2) = u2 * d(2) - g(2) + x(of(2) + 6)
          g(3) = u2 * d(3) - g(3) + w(of(1) + 6)
          g(4) = u2 * d(4) - g(4) + w(of(2) + 6)
          d(1) = u2 * g(1) - d(1) + x(of(1) + 5)
          d(2) = u2 * g(2) - d(2) + x(of(2) + 5)
          d(3) = u2 * g(3) - d(3) + w(of(1) + 5)
          d(4) = u2 * g(4) - d(4) + w(of(2) + 5)
          g(1) = u2 * d(1) - g(1) + x(of(1) + 4)
          g(2) = u2 * d(2) - g(2) + x(of(2) + 4)
          g(3) = u2 * d(3) - g(3) + w(of(1) + 4)
          g(4) = u2 * d(4) - g(4) + w(of(2) + 4)
          d(1) = u2 * g(1) - d(1) + x(of(1) + 3)
          d(2) = u2 * g(2) - d(2) + x(of(2) + 3)
          d(3) = u2 * g(3) - d(3) + w(of(1) + 3)
          d(4) = u2 * g(4) - d(4) + w(of(2) + 3)
          g(1) = u2 * d(1) - g(1) + x(of(1) + 2)
          g(2) = u2 * d(2) - g(2) + x(of(2) + 2)
          g(3) = u2 * d(3) - g(3) + w(of(1) + 2)
          g(4) = u2 * d(4) - g(4) + w(of(2) + 2)
          im(1, j) = uu * g(1) - d(1) + x(of(1) + 1) * 0.5d0
          im(2, j) = uu * g(2) - d(2) + x(of(2) + 1) * 0.5d0
          im(3, j) = uu * g(3) - d(3) + w(of(1) + 1) * 0.5d0
          im(4, j) = uu * g(4) - d(4) + w(of(2) + 1) * 0.5d0
